public int minimumNumber(int n, String password) {
    boolean hasDigit = false, hasLower = false, hasUpper = false, hasSpecial = false;
    String special = "!@#$%^&*()-+";
    for (int i = 0; i < password.length(); i++) {
        char c = password.charAt(i);
        if (Character.isDigit(c)) hasDigit = true;
        else if (Character.isLowerCase(c)) hasLower = true;
        else if (Character.isUpperCase(c)) hasUpper = true;
        else if (special.indexOf(c) >= 0) hasSpecial = true;
    }
    int missing = (hasDigit ? 0 : 1) + (hasLower ? 0 : 1)
                + (hasUpper ? 0 : 1) + (hasSpecial ? 0 : 1);
    int lengthDeficit = Math.max(0, 6 - n);
    return Math.max(missing, lengthDeficit);
}
